<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php'; require_login(); $page_title='Equipment'; require __DIR__.'/../includes/header.php'; $q=trim($_GET['q']??'');$status=$_GET['status']??'';$where=[];$params=[];if($q!==''){$where[]='(serial_number LIKE ? OR equipment_name LIKE ? OR category LIKE ? OR location LIKE ?)';for($i=0;$i<4;$i++)$params[]="%$q%";}if($status!==''){$where[]='status=?';$params[]=$status;}$sql='SELECT equipment.*, (SELECT COUNT(*) FROM maintenance_records mr WHERE mr.equipment_id=equipment.id AND mr.status="Completed") repair_count, (SELECT MAX(mr.maintenance_date) FROM maintenance_records mr WHERE mr.equipment_id=equipment.id AND mr.status="Completed") last_repair FROM equipment'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC';$s=$pdo->prepare($sql);$s->execute($params);$items=$s->fetchAll(PDO::FETCH_ASSOC); ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="page-heading"><?=e(t('equipment'))?></h1><p class="page-subtitle mb-0"><?=e(t('equipment_overview'))?></p></div><?php if(is_system_admin()):?><a href="add.php" class="btn btn-primary"><i class="bi bi-plus-lg"></i> <?=e(t('add_equipment'))?></a><?php endif?></div><div class="panel"><form class="row g-2 mb-4"><div class="col-md-6"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search name, serial number, category or location"></div><div class="col-md-3"><select class="form-select" name="status"><option value=""><?=e(t('all_statuses'))?></option><?php foreach(['Operational','Under Maintenance','Breakdown','Retired'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=e(tv($x))?></option><?php endforeach?></select></div><div class="col-md-3"><button class="btn btn-dark"><?=e(t('filter'))?></button><a href="index.php" class="btn btn-light"><?=e(t('reset'))?></a></div></form><div class="table-responsive"><table class="table table-hover"><thead><tr><th><?=e(t('serial_number'))?></th><th><?=e(t('name'))?></th><th><?=e(t('category'))?></th><th><?=e(t('location'))?></th><th><?=e(t('status'))?></th><th>Repair Count</th><th>Last Repair</th><th class="text-end"><?=e(t('action'))?></th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><b><?=e($x['serial_number']??'—')?></b></td><td><?=e($x['equipment_name'])?></td><td><?=e($x['category'])?></td><td><?=e($x['location'])?></td><td><span class="badge status-<?=str_replace(' ','-',$x['status'])?>"><?=e(tv($x['status']))?></span></td><td><span class="badge text-bg-primary"><?=(int)$x['repair_count']?></span></td><td><?=e($x['last_repair']??'Never repaired')?></td><td class="text-end"><a class="btn btn-sm btn-light" href="view.php?id=<?=$x['id']?>"><?=e(t('view'))?></a><?php if(is_system_admin()):?><a class="btn btn-sm btn-light" href="edit.php?id=<?=$x['id']?>"><?=e(t('edit'))?></a><?php endif?></td></tr><?php endforeach;if(!$items):?><tr><td colspan="8" class="empty"><?=e(t('no_equipment'))?></td></tr><?php endif?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
